import {escapeHTML as e} from './core.js';
const genres={Action:'Боевик',Adventure:'Приключения',Animation:'Мультфильм',Biography:'Биография',Comedy:'Комедия',Crime:'Криминал',Documentary:'Документальный',Drama:'Драма',Family:'Семейный',Fantasy:'Фэнтези',History:'История',Horror:'Ужасы',Mystery:'Детектив',Romance:'Мелодрама','Sci-Fi':'Фантастика',Sport:'Спорт',Thriller:'Триллер',War:'Военный',Western:'Вестерн'};
const genreLabels={...genres,Short:'Короткометражный',Music:'Музыка',Musical:'Мюзикл','Film-Noir':'Нуар'};
const countries={'United States':'США','United Kingdom':'Великобритания',Russia:'Россия','Soviet Union':'СССР',France:'Франция',Germany:'Германия',Italy:'Италия',Spain:'Испания',Canada:'Канада',Australia:'Австралия',Japan:'Япония','South Korea':'Южная Корея',China:'Китай','Hong Kong':'Гонконг',India:'Индия',Sweden:'Швеция',Denmark:'Дания',Norway:'Норвегия',Finland:'Финляндия',Poland:'Польша','Czech Republic':'Чехия',Mexico:'Мексика',Brazil:'Бразилия',Argentina:'Аргентина',Iran:'Иран',Turkey:'Турция','New Zealand':'Новая Зеландия',Belgium:'Бельгия',Netherlands:'Нидерланды'};
export function parseCSV(text){const first=text.replace(/^\uFEFF/,'').split(/\r?\n/)[0],delimiter=[';',',','\t'].sort((a,b)=>first.split(b).length-first.split(a).length)[0];const rows=[];let row=[],cell='',quoted=false;text=text.replace(/^\uFEFF/,'');for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===delimiter&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw Error('В CSV не закрыты кавычки.');row.push(cell);if(row.some(v=>v.trim()))rows.push(row);const header=rows.shift()?.map(s=>s.trim());if(!header?.length)return [];return rows.map(r=>Object.fromEntries(header.map((h,i)=>[h,r[i]||''])));}
export function parseWatched(text,name){if(name.toLowerCase().endsWith('.json')){const d=JSON.parse(text.replace(/^\uFEFF/,''));const rows=Array.isArray(d)?d:d.watched||d.ratings||d.movies||d.films||d.items;if(!Array.isArray(rows))throw Error('Нужен JSON со списком фильмов.');return rows;}if(!/\.(csv|tsv|txt)$/i.test(name))throw Error('Пока поддерживаются CSV и JSON. Импорт профиля Кинопоиска добавим отдельно.');return parseCSV(text);}
export function createDiscovery({request,onSearch,onMessage}){
 const defaults={yearFrom:1990,yearTo:new Date().getFullYear(),rating:7,count:3,genre:'',excludeGenre:'',country:'',excludeCountry:''};let saved;try{saved=JSON.parse(localStorage.getItem('wn-discover-filters'));}catch{}
 const s={filters:{...defaults,...saved},movies:[],skip:[],fingerprint:'',busy:false,error:'',note:'',status:null,loaded:false,remaining:null};
 const host=()=>document.querySelector('#discovery');
 const option=(value,label,selected)=>`<option value="${e(value)}" ${String(value)===String(selected)?'selected':''}>${e(label)}</option>`;
 const select=(name,label,values,empty='Любой')=>`<label class="field"><span>${e(label)}</span><select name="${name}">${option('',empty,s.filters[name])}${Object.entries(values).map(([v,t])=>option(v,t,s.filters[name])).join('')}</select></label>`;
 function results(){return `${s.error?`<p class="discover-error" role="alert">${e(s.error)}</p>`:''}${s.note?`<p class="help" role="status">${e(s.note)}</p>`:''}${s.busy?'<div class="spinner" role="status" aria-label="Подбираем фильмы"></div><p class="help center">Ищем фильмы по выбранным фильтрам…</p>':''}${s.movies.length?`<div class="discover-cards">${s.movies.map(m=>`<article class="discover-card" data-movie="${e(m.imdb_id)}"><div class="discover-movie-head"><div class="discover-poster"><span class="poster-placeholder" aria-hidden="true"><svg viewBox="0 0 24 24"><rect x="4" y="3" width="16" height="18" rx="2"/><path d="m10 8 6 4-6 4z"/></svg><small>Обложка</small></span><img src="/api/discover/poster/${e(m.imdb_id)}" alt="" loading="lazy" referrerpolicy="no-referrer" data-discover-poster></div><div><div class="discover-rating">${m.ratingSource==='TMDB'?`TMDB ${e(Number(m.tmdbRating).toFixed(1))}`:m.rating!==null?`IMDb ${e(m.rating)}`:'Без оценки'} <span>· ${e(m.year)}</span></div><h3>${e(m.title)}</h3>${m.title!==m.original_title?`<p class="meta">${e(m.original_title)}</p>`:''}<p class="meta">${e(m.genres.map(g=>genreLabels[g]||g).join(' · '))}</p><p class="meta">${e(m.countries.map(c=>countries[c]||c).join(', '))}</p></div></div><details><summary>${m.detailsLoading?'О фильме · загружаем описание…':'О фильме'}</summary>${m.descriptionLanguage==='ru'?`<p class="help">${e(m.description)}</p>${(m.descriptionURL||m.wikiURL)?`<a class="discover-imdb" href="${e(m.descriptionURL||m.wikiURL)}" target="_blank" rel="noopener noreferrer">Источник: ${e(m.descriptionSource||'Википедия')} ↗</a>`:''}`:m.detailsLoading?'<p class="help">Загружаем русское описание…</p>':`<p class="help">Русское описание пока недоступно.${m.description?' Ниже — оригинал на английском.':''}</p>${m.description?`<p class="help" lang="en">${e(m.description)}</p>`:''}`}</details><div class="discover-card-actions"><button type="button" class="primary small" data-discover="search" data-id="${e(m.imdb_id)}">Найти раздачи</button><button type="button" class="secondary outline small" data-discover="seen" data-id="${e(m.imdb_id)}" ${s.busy?'disabled':''}>Смотрел</button><a class="discover-imdb" href="https://www.imdb.com/title/${e(m.imdb_id)}/" target="_blank" rel="noopener noreferrer">IMDb ↗</a></div></article>`).join('')}</div>`:!s.busy&&s.remaining!==null&&!s.error?'<div class="discover-empty"><h3>Новых совпадений пока нет</h3><p class="help">Расширьте годы, снизьте рейтинг или нажмите «Подобрать фильмы», чтобы получить другие варианты.</p></div>':''}${s.movies.length?`<button class="secondary outline full" type="button" data-discover="more" ${s.busy?'disabled':''}>Ещё варианты</button>`:''}`;}
 function history(){return `<strong>Просмотренное</strong><p class="help">${s.status?`Сохранено: ${s.status.watchedCount}`:'Загружаем список…'}</p><div class="discover-history-actions"><button class="secondary outline small" type="button" data-discover="import" ${s.busy?'disabled':''}>Загрузить список</button><button class="secondary outline small" type="button" data-discover="export" ${s.busy?'disabled':''}>Скачать список</button></div><input id="discover-file" type="file" accept=".json,.csv,.tsv,.txt" hidden><p class="help">CSV / JSON: IMDb, TMDB или Кинопоиск ID; также название + год. Загружайте только просмотренное, без «Буду смотреть». История хранится на мини‑ПК. Подключение профиля Кинопоиска добавим позже.</p>`;}
 function html(){const f=s.filters;return `<section id="discovery"><div class="discover-intro"><span class="discover-kicker">ВЕЧЕР БЕЗ ДОЛГИХ ПОИСКОВ</span><h2>Случайный фильм</h2><p>Задайте настроение — предложим несколько фильмов.</p></div><form id="discover-form"><div class="discover-grid"><label class="field"><span>Год от</span><input type="number" inputmode="numeric" name="yearFrom" min="1870" max="${defaults.yearTo}" value="${e(f.yearFrom)}" required></label><label class="field"><span>Год до</span><input type="number" inputmode="numeric" name="yearTo" min="1870" max="${defaults.yearTo}" value="${e(f.yearTo)}" required></label>${select('genre','Жанр',s.status?.genres||genres)}${select('country','Страна',countries,'Любая')}<label class="field"><span data-rating-label>Рейтинг источника от</span><select name="rating">${[0,5,6,6.5,7,7.5,8,8.5,9].map(v=>option(v,v===0?'Любой':v+'+',f.rating)).join('')}</select></label><label class="field"><span>Предложить фильмов</span><select name="count">${[1,3,5,10].map(v=>option(v,v,f.count)).join('')}</select></label></div><details class="discover-exclusions"><summary>Исключить жанр или страну</summary><div class="discover-grid">${select('excludeGenre','Без жанра',s.status?.genres||genres,'Не исключать')}${select('excludeCountry','Без страны',countries,'Не исключать')}</div></details><button type="submit" class="primary full" ${s.busy?'disabled':''}>${s.busy?'Подбираем…':'Подобрать фильмы'}</button><p class="help">Просмотренные и уже показанные фильмы не повторяются.</p></form><div id="discover-results" aria-live="polite">${results()}</div><details class="discover-history"><summary>Мой список просмотренного${s.status?` · ${s.status.watchedCount}`:''}</summary><div id="discover-history">${history()}</div></details><p class="sources" data-discover-source>Источник: <a href="https://www.themoviedb.org" target="_blank" rel="noopener noreferrer">TMDB</a>. Для случайного подбора нужен настроенный доступ TMDB.</p></section>`;}
 function update(){const el=host();if(!el)return;const open=new Set([...el.querySelectorAll('.discover-card details[open]')].map(d=>d.closest('[data-movie]').dataset.movie));if(s.status){el.querySelector('[data-rating-label]').textContent='Рейтинг '+s.status.ratingSource+' от';if(s.status.provider==='TMDB'){el.querySelector('[data-discover-source]').innerHTML='Источник: <a href="https://www.themoviedb.org" target="_blank" rel="noopener noreferrer">TMDB</a>. Фильмы подбираются напрямую в TMDB. При минимальном рейтинге — от 50 голосов.';for(const name of ['genre','excludeGenre']){const sel=el.querySelector('[name="'+name+'"]');const allowed=s.status.genres;for(const option of [...sel.options])if(option.value&&!allowed[option.value])option.remove();if(s.filters[name]&&!allowed[s.filters[name]]){s.filters[name]='';sel.value='';}}}}el.querySelector('#discover-results').innerHTML=results();for(const d of el.querySelectorAll('.discover-card details'))if(open.has(d.closest('[data-movie]').dataset.movie))d.open=true;el.querySelector('#discover-history').innerHTML=history();el.querySelector('.discover-history>summary').textContent='Мой список просмотренного'+(s.status?' · '+s.status.watchedCount:'');el.querySelector('[type=submit]').disabled=s.busy;el.querySelector('[type=submit]').textContent=s.busy?'Подбираем…':'Подобрать фильмы';}
 function capture(){const form=host()?.querySelector('form');if(form){s.filters=Object.fromEntries(new FormData(form));try{localStorage.setItem('wn-discover-filters',JSON.stringify(s.filters));}catch{}}}
 async function status(){try{s.status=await request('/api/discover/status');}catch(err){s.error=err.message;}update();}
 let detailsEpoch=0;
 async function loadDetails(movies){const epoch=++detailsEpoch;if(!movies.length)return;try{const d=await request('/api/discover/details',{method:'POST',body:{ids:movies.map(m=>m.imdb_id)}});if(epoch!==detailsEpoch)return;s.movies=s.movies.map(m=>({...m,...d.movies.find(r=>r.imdb_id===m.imdb_id),detailsLoading:false}));}catch{if(epoch!==detailsEpoch)return;s.movies=s.movies.map(m=>({...m,detailsLoading:false}));}update();}
 async function pick(){if(s.busy)return;capture();const fingerprint=JSON.stringify(s.filters);if(fingerprint!==s.fingerprint){s.skip=[];s.movies=[];s.fingerprint=fingerprint;}s.busy=true;s.error='';s.note='';update();try{const d=await request('/api/discover/pick',{method:'POST',body:{...s.filters,skip:s.skip}});s.movies=d.movies.map(m=>({...m,detailsLoading:m.descriptionLanguage!=='ru'}));s.skip=[...new Set([...s.skip,...s.movies.map(m=>m.imdb_id)])];s.remaining=d.matches;s.note=[d.warning,d.remote?`В TMDB найдено ${d.matches} фильмов по основным фильтрам. Просмотренное и дополнительные исключения проверяются отдельно.`:'Поиск выполнен в TMDB.'].filter(Boolean).join(' ');await status();}catch(err){s.error=err.message;}finally{s.busy=false;update();if(!s.error)loadDetails(s.movies);}}
 async function seen(m){if(s.busy)return;s.busy=true;update();try{await request('/api/discover/seen',{method:'POST',body:{movie:m}});s.movies=s.movies.filter(x=>x.imdb_id!==m.imdb_id);await status();onMessage('Фильм исключён из будущих подборок');}catch(err){s.error=err.message;}finally{s.busy=false;update();}}
 async function upload(file){if(!file||s.busy)return;s.busy=true;s.error='';update();try{if(file.size>4*1024*1024)throw Error('Файл должен быть не больше 4 МБ.');const buffer=await file.arrayBuffer();let text=new TextDecoder('utf-8').decode(buffer);if(text.includes('\uFFFD'))text=new TextDecoder('windows-1251').decode(buffer);const rows=parseWatched(text,file.name);if(rows.length>20000)throw Error('В файле больше 20 000 строк.');const d=await request('/api/discover/watched',{method:'POST',body:{rows}});s.note=`Распознано ${d.accepted}, новых ${d.added}, пропущено ${d.skipped}.${d.kpOnly?' Для ID Кинопоиска используем подтверждённые соответствия каталога.':''}`;s.movies=[];s.skip=[];s.remaining=null;await status();}catch(err){s.error=err.message;}finally{s.busy=false;update();}}
 function mount(){const el=host();if(!el)return;el.addEventListener('error',event=>{if(event.target.matches?.('[data-discover-poster]')){event.target.hidden=true;event.target.parentElement.querySelector('small').textContent='Нет обложки';}},true);el.querySelector('form').addEventListener('submit',event=>{event.preventDefault();event.stopPropagation();pick();});el.addEventListener('change',event=>{if(event.target.id==='discover-file')upload(event.target.files[0]);else if(event.target.closest('form'))capture();});el.addEventListener('click',async event=>{const button=event.target.closest('[data-discover]');if(!button)return;const action=button.dataset.discover,m=s.movies.find(m=>m.imdb_id===button.dataset.id);if(action==='search'&&m)onSearch(m);if(action==='seen'&&m)seen(m);if(action==='more')pick();if(action==='import')el.querySelector('#discover-file').click();if(action==='export'){try{const rows=await request('/api/discover/watched');const text=JSON.stringify(rows,null,2);const android=/WatchNextAndroid\//.test(navigator.userAgent);const url=android?'data:application/json;charset=utf-8,'+encodeURIComponent(text):URL.createObjectURL(new Blob([text],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='watchnext-watched.json';a.click();if(!android)setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(err){s.error=err.message;update();}}});s.loaded=true;status();}
 return {html,mount};
}
